const $=s=>document.querySelector(s);let billing='monthly',toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function readBookings(){try{return JSON.parse(localStorage.getItem('form-bookings')||'[]')}catch{return []}}
const schedule={Mon:[['07:00','Strength Lab','Alex Morgan'],['12:30','Restore & Flow','Jamie Lee'],['18:00','Engine Room','Nadia Reyes']],Tue:[['07:30','Engine Room','Nadia Reyes'],['17:30','Strength Lab','Alex Morgan']],Wed:[['07:00','Strength Lab','Alex Morgan'],['12:30','Restore & Flow','Jamie Lee'],['18:30','Engine Room','Nadia Reyes']],Thu:[['08:00','Restore & Flow','Jamie Lee'],['18:00','Strength Lab','Alex Morgan']],Fri:[['07:00','Engine Room','Nadia Reyes'],['17:00','Restore & Flow','Jamie Lee']],Sat:[['09:00','Strength Lab','Alex Morgan'],['10:30','Restore & Flow','Jamie Lee']]};
function renderSessions(day){const bookings=readBookings();$('#sessions').replaceChildren();schedule[day].forEach(([time,title,coach])=>{const key=`${day} ${time} ${title}`,row=document.createElement('div');row.className='session';const t=document.createElement('span');t.textContent=time;const name=document.createElement('strong');name.textContent=title;const c=document.createElement('small');c.textContent=coach;const b=document.createElement('button');b.textContent=bookings.includes(key)?'Cancel':'Reserve ↗';b.setAttribute('aria-label',`${bookings.includes(key)?'Cancel':'Reserve'} ${title} ${day} ${time}`);b.onclick=()=>{const current=readBookings();const next=current.includes(key)?current.filter(x=>x!==key):[...current,key];try{localStorage.setItem('form-bookings',JSON.stringify(next));renderSessions(day);toast(next.includes(key)?'Demo reservation saved on this device.':'Demo reservation removed.')}catch{toast('This browser could not save the reservation.')}};row.append(t,name,c,b);$('#sessions').append(row)})}
document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-day]').forEach(x=>x.classList.toggle('active',x===b));renderSessions(b.dataset.day)});renderSessions('Mon');
document.querySelectorAll('[data-billing]').forEach(b=>b.onclick=()=>{billing=b.dataset.billing;document.querySelectorAll('[data-billing]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-price]').forEach(p=>{const base=Number(p.dataset.price);p.replaceChildren(document.createTextNode(`$${billing==='annual'?(base*.85).toFixed(2):base}`));const span=document.createElement('span');span.textContent=billing==='annual'?`/ mo · $${(base*.85*12).toFixed(2)} yearly`:'/ month';p.append(span)})});
const dialog=$('#join-dialog');document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{$('#selected-plan').textContent=b.dataset.plan;$('#join-description').textContent=`${b.dataset.plan} · ${billing} billing. Preview your interest; no payment is collected.`;$('#join-status').textContent='';dialog.showModal()});$('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$('#join-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{localStorage.setItem('form-interest',JSON.stringify({name:f.get('name'),email:f.get('email'),plan:$('#selected-plan').textContent,billing}));$('#join-status').textContent='Demo interest saved on this device. No information has been sent to a business.'}catch{$('#join-status').textContent='Your browser could not save this. Please allow local storage and try again.'}};
$('.clear-data').onclick=()=>{try{localStorage.removeItem('form-interest');localStorage.removeItem('form-bookings');$('#join-form').reset();$('#join-status').textContent='All saved FORM demo data cleared.';renderSessions($('.filters .active').dataset.day)}catch{$('#join-status').textContent='Your browser could not clear local data.'}};
$('#program-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),days=Number(f.get('days')),age=Number(f.get('age')),level=f.get('level'),goal=f.get('goal'),minutes=Number(f.get('duration'));const gentle=level==='beginner'||age>=65;const intensity=gentle?'Comfortable pace; stop with 3–4 repetitions in reserve.':'Moderate effort; stop with 2–3 repetitions in reserve.';const strength={name:'Strength foundations',detail:`5 min warm-up · ${gentle?'2':'3'} sets of supported squat, incline push-up, band row, hip hinge and carry. Rest 60–90 sec between sets.`};const cardio={name:'Aerobic base',detail:`5 min easy warm-up · ${Math.max(10,minutes-15)} min walk, cycle or elliptical at a conversational pace · 5 min cool-down.`};const mobility={name:'Mobility & balance',detail:'Gentle ankle, hip and shoulder mobility, supported single-leg balance, and easy walking. Keep every movement comfortable.'};const library=goal==='endurance'?[cardio,strength,cardio,mobility,cardio]:goal==='mobility'?[mobility,strength,mobility,cardio,strength]:goal==='fitness'?[strength,cardio,mobility,strength,cardio]:[strength,cardio,strength,mobility,strength];const dayMap={2:['Monday','Thursday'],3:['Monday','Wednesday','Friday'],4:['Monday','Tuesday','Thursday','Saturday'],5:['Monday','Tuesday','Thursday','Friday','Saturday']};const result=$('#program-result');result.replaceChildren();const eyebrow=document.createElement('div');eyebrow.className='eyebrow';eyebrow.textContent='YOUR STARTING SCHEDULE';const h=document.createElement('h3');h.textContent=`${days} days. A rhythm for you.`;const note=document.createElement('p');note.className='caption';note.textContent=`${minutes} minutes per session. ${intensity} This is a general suggestion for an adult, not a medical or rehabilitation program. Review it with a qualified coach, especially if you have symptoms, injuries or health conditions.`;result.append(eyebrow,h,note);dayMap[days].forEach((day,i)=>{const row=document.createElement('div');row.className='result-day';const strong=document.createElement('strong');strong.textContent=`${day} / ${library[i].name}`;const p=document.createElement('p');p.textContent=library[i].detail;row.append(strong,p);result.append(row)});const recovery=document.createElement('p');recovery.className='caption';recovery.textContent='Other days: rest or an easy walk. Start with short sessions, leave recovery between strength days, and increase gradually only when comfortable. Height, weight and gender are profile context; they are not used to infer ability or prescribe calories.';const button=document.createElement('button');button.className='button';button.textContent='Adjust my profile ↗';button.onclick=()=>{result.hidden=true;e.target.hidden=false;e.target.querySelector('input').focus()};const print=document.createElement('button');print.className='text-link';print.style.marginTop='15px';print.textContent='Download my schedule ↓';print.onclick=()=>{const blob=new Blob([result.innerText.replace('Adjust my profile ↗','').replace('Download my schedule ↓','')],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-form-schedule.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};result.append(recovery,button,print);e.target.hidden=true;result.hidden=false;h.tabIndex=-1;h.focus()};
